response:
I copied round 3's script as the base. The gates are below, then the full script for `spe/evals/harness/r04-workflow.js`.

**Gates before launch.** First I commit the script as `spe/evals/harness/r04-workflow.js`, because you asked for a commit after each step. Then I run the gates in order and stop at the first one that fails.
1. I check with `git log` that `spe/predictions/r04.yaml` and `spe/plans/r04.md` are committed. I also check that `spe/evals/tasks/answers.json` holds 50 tickets, because the set had 40 in earlier rounds.
2. I run the grader selftest. `grade.py` must score the oracle labels, copied from `answers.json`, at 50 of 50. It must fail an empty labels file and a file with every category shifted to the wrong one.
3. I regrade round 3's saved trial outputs with this `grade.py` as a control. If the round 3 numbers move, the grader changed. I would log that in `spe/failures.md` with both numbers side by side before going on. If the grader is broken, I halt and report.
4. I do a dry run with `{only: ['B:T001', 'C2:T001', 'C2:T017'], trials: 1, capUsd: 2}`. It must return valid trials, a leak scan, grades, and judge scores. I use the dry run's real cost per trial to check that 500 trials plus 50 judge calls fit under $40. If they do not fit, I halt and ask you before launching.

**Defaults I chose:**
- Ticket files are at `spe/evals/tasks/tickets/T001.json` through `T050.json`.
- The agent runs with `python -m triage run --config <B|C2>`.
- `grade.py` takes `--answers`, `--labels`, and `--json`, and prints one result per trial.
- The headline numbers use only the 5 base trials per cell, so they match the prediction. Top-up trials are reported separately.

```js
export const meta = {
  name: 'triage-spe-eval',
  description: 'SPE eval for the triage agent. Runs each config on each ticket, scans for answer-key reads, grades labels with grade.py, tops up split cells, judges reply tone blind with Opus, then runs failure analysis and a completeness critic.',
  phases: [
    { title: 'Trials' },
    { title: 'Leak scan' },
    { title: 'Grade' },
    { title: 'Top-up' },
    { title: 'Judge' },
    { title: 'Synthesis' },
  ],
};

// ---------- Round and arguments (the round number lives only here) ----------
const ROUND = args.round ?? 4;
const RR = String(ROUND).padStart(2, '0');
const CONFIGS = args.configs ?? ['B', 'C2'];
const TICKET_COUNT = args.tickets ?? 50;
const TRIALS = args.trials ?? 5;
const CAP_USD = args.capUsd ?? 40;
const EST_TRIAL_USD = args.estTrialUsd ?? 0.04;   // unmeasured estimate. The dry run replaces it.
const EST_JUDGE_USD = args.estJudgeUsd ?? 0.12;   // unmeasured estimate, one Opus call per ticket
const TOPUP_MAX = args.topupMax ?? 3;             // extra trials per split cell
const RUNNER_MODEL = args.runnerModel ?? 'opus';
const JUDGE_MODEL = 'opus';
const DRY = Array.isArray(args.only) && args.only.length > 0;
const RESULTS_DIR = `spe/evals/results/r${RR}${DRY ? '-dryrun' : ''}`;
const RUN_DIR = `.spe-runs/r${RR}${DRY ? '-dryrun' : ''}`;

const FORBIDDEN = [
  'spe/evals/graders/',
  'spe/evals/tasks/answers.json',
  'spe/evals/results/',
  'spe/evals/harness/',
  'spe/predictions/',
  'spe/plans/',
  'spe/spec/',
  'spe/prediction-log.md',
  'spe/failures.md',
];

const TICKETS = args.ticketIds ??
  Array.from({ length: TICKET_COUNT }, (_, i) => 'T' + String(i + 1).padStart(3, '0'));

let cells = [];
for (const config of CONFIGS) for (const ticket of TICKETS) cells.push({ config, ticket, key: `${config}:${ticket}` });
if (DRY) cells = cells.filter(c => args.only.includes(c.key));

// ---------- Helpers ----------
const r2 = x => Math.round(x * 100) / 100;
const mean = xs => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
const chunk = (xs, n) => { const out = []; for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n)); return out; };

function rng(seedStr) {
  let a = 0;
  for (const ch of seedStr) a = (Math.imul(a, 31) + ch.charCodeAt(0)) | 0;
  return () => {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function shuffle(arr, seedStr) {
  const r = rng(seedStr); const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

// ---------- Budget ----------
let spentUsd = 0;
const skips = [];
function reserve(kind, id, est, headroom = 0) {
  if (spentUsd + est + headroom > CAP_USD) {
    skips.push({ kind, id, est_usd: est, spent_usd: r2(spentUsd), headroom_usd: r2(headroom) });
    log(`SKIP ${kind} ${id}: $${est} would cross the $${CAP_USD} cap (spent $${spentUsd.toFixed(2)}, held back $${headroom.toFixed(2)})`);
    return false;
  }
  spentUsd += est;
  return true;
}
function settle(est, actual) {
  if (typeof actual === 'number' && actual >= 0) spentUsd += actual - est;
}

// ---------- Schemas ----------
const NUM = { type: 'number' };
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['status', 'transcript_path', 'metrics'],
  properties: {
    status: { enum: ['completed', 'harness_error'] },
    error: { type: 'string' },
    label: {
      type: 'object',
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    transcript_path: { type: 'string' },
    commands_run: { type: 'array', items: { type: 'string' } },
    metrics: {
      type: 'object',
      required: ['runtime_s', 'tool_calls', 'tool_errors', 'input_tokens', 'output_tokens', 'cost_usd'],
      properties: { runtime_s: NUM, tool_calls: NUM, tool_errors: NUM, input_tokens: NUM, output_tokens: NUM, cost_usd: NUM },
    },
  },
};
const SCAN_SCHEMA = {
  type: 'object',
  required: ['scanned', 'hits', 'missing'],
  properties: {
    scanned: { type: 'integer' },
    hits: { type: 'array', items: { type: 'object', required: ['trial_id', 'pattern', 'line'],
      properties: { trial_id: { type: 'string' }, pattern: { type: 'string' }, line: { type: 'string' } } } },
    missing: { type: 'array', items: { type: 'string' } },
  },
};
const GRADE_SCHEMA = {
  type: 'object',
  required: ['status', 'results'],
  properties: {
    status: { enum: ['ok', 'grader_error'] },
    stderr: { type: 'string' },
    results: { type: 'array', items: { type: 'object',
      required: ['trial_id', 'category_ok', 'priority_ok'],
      properties: {
        trial_id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' },
        expected_category: { type: 'string' }, expected_priority: { type: 'string' },
      } } },
  },
};
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: { type: 'array', items: { type: 'object',
      required: ['reply_id', 'tone_score', 'pass', 'reason'],
      properties: { reply_id: { type: 'string' }, tone_score: { type: 'integer', minimum: 1, maximum: 5 },
        pass: { type: 'boolean' }, reason: { type: 'string' } } } },
  },
};
const FAILURE_SCHEMA = {
  type: 'object',
  required: ['failure_types', 'proposals'],
  properties: {
    failure_types: { type: 'array', items: { type: 'object',
      required: ['name', 'kind', 'configs', 'trial_ids', 'what', 'how_to_spot', 'proposed_fix'],
      properties: { name: { type: 'string' }, kind: { type: 'string' }, configs: { type: 'array', items: { type: 'string' } },
        trial_ids: { type: 'array', items: { type: 'string' } }, what: { type: 'string' }, how_to_spot: { type: 'string' },
        proposed_fix: { type: 'string' }, matches_existing: { type: 'string' } } } },
    proposals: { type: 'array', items: { type: 'object', required: ['change', 'reason', 'evidence'],
      properties: { change: { type: 'string' }, reason: { type: 'string' }, evidence: { type: 'string' } } } },
  },
};
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'object', required: ['issue', 'severity', 'fix'],
      properties: { issue: { type: 'string' }, severity: { enum: ['blocker', 'major', 'minor'] }, fix: { type: 'string' } } } },
  },
};

// ---------- Trials ----------
function trialPrompt(cell, trialId) {
  return `You run one trial of the triage agent. Your only job is to run the command below and report what it printed.

Rules:
- You may read only triage/ (the agent's code and configs) and spe/evals/tasks/tickets/${cell.ticket}.json.
- Do not open, list, grep, or cat anything else under spe/. Never touch any of these: ${FORBIDDEN.join(', ')}.
- Do not change any file. Do not retry with another config or ticket. Do not edit or improve the agent's output.

Command:
  mkdir -p ${RUN_DIR}/transcripts && python -m triage run --config ${cell.config} --ticket spe/evals/tasks/tickets/${cell.ticket}.json --transcript ${RUN_DIR}/transcripts/${trialId}.jsonl --json

From the JSON output, copy label.category, label.priority, and reply exactly as printed, even if they look wrong.
Copy the usage block into metrics: runtime_s, tool_calls, tool_errors, input_tokens, output_tokens, cost_usd.
Set transcript_path to ${RUN_DIR}/transcripts/${trialId}.jsonl. List every shell command you ran in commands_run.
If the command exits nonzero, hits a rate limit, or prints invalid JSON, set status to "harness_error" and put the error text in error. A harness error is not a wrong answer.`;
}

async function runTrial(cell, n, kind, headroom = 0) {
  const trialId = `${cell.config}-${cell.ticket}-${kind === 'topup' ? 'u' : 't'}${n}`;
  const base = { trialId, config: cell.config, ticket: cell.ticket, key: cell.key, kind };
  if (!reserve('trial', trialId, EST_TRIAL_USD, headroom)) return { ...base, status: 'skipped' };
  const out = await agent(trialPrompt(cell, trialId), {
    label: `trial ${trialId}`,
    phase: kind === 'topup' ? 'Top-up' : 'Trials',
    schema: TRIAL_SCHEMA,
    model: RUNNER_MODEL,
  });
  settle(EST_TRIAL_USD, out?.metrics?.cost_usd);
  return { ...base, ...(out ?? { status: 'harness_error', error: 'runner returned no result' }) };
}

// ---------- Leak scan ----------
async function scanTrials(trials, tag, phaseName) {
  const items = trials.filter(t => t.status === 'completed');
  const batches = chunk(items, 100);
  const results = await parallel(batches.map((b, i) => () => agent(
`You check eval trial transcripts for reads of files the trial was not allowed to see.

Forbidden strings:
${FORBIDDEN.join('\n')}

For each transcript below, search the file with grep -n -F for each forbidden string.
A hit counts only if the string appears in a tool call or tool input made by the agent (Read, Grep, Glob, Bash, or a file open). Text inside the ticket body does not count.
Quote the matching line in line. List every trial whose transcript is missing or empty in missing. Do not change any file.

Transcripts (trial_id path):
${b.map(t => `${t.trialId} ${t.transcript_path}`).join('\n')}`,
    { label: `leak scan ${tag} ${i + 1}`, phase: phaseName, schema: SCAN_SCHEMA, model: RUNNER_MODEL })));

  const voided = [];
  results.forEach((r, i) => {
    if (!r) { for (const t of batches[i]) { t.void = 'scan failed'; voided.push({ trial_id: t.trialId, reason: 'scan failed' }); } return; }
    for (const h of r.hits) {
      const t = items.find(x => x.trialId === h.trial_id);
      if (t && !t.void) { t.void = 'peeked'; voided.push({ trial_id: t.trialId, reason: 'peeked', pattern: h.pattern, line: h.line }); }
    }
    for (const id of r.missing) {
      const t = items.find(x => x.trialId === id);
      if (t && !t.void) { t.void = 'no transcript'; voided.push({ trial_id: id, reason: 'no transcript' }); }
    }
  });
  for (const v of voided) log(`VOID ${v.trial_id}: ${v.reason}${v.pattern ? ` (${v.pattern})` : ''}`);
  return voided;
}

// ---------- Code grade ----------
async function gradeTrials(trials, tag, phaseName) {
  const items = trials.filter(t => t.status === 'completed' && !t.void);
  const batches = chunk(items, 100);
  const results = await parallel(batches.map((b, i) => {
    const file = `${RESULTS_DIR}/labels/${tag}-${i + 1}.json`;
    const payload = b.map(t => ({ trial_id: t.trialId, ticket_id: t.ticket,
      category: t.label?.category ?? null, priority: t.label?.priority ?? null }));
    return () => agent(
`You run the code grader for an eval. You do not grade anything yourself.

1. Create ${RESULTS_DIR}/labels/ if needed. Write this JSON array to ${file} exactly as given:
${JSON.stringify(payload)}
2. Run: python spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --labels ${file} --json
3. Return the grader's per-trial results as printed. Copy category_ok, priority_ok, expected_category, and expected_priority exactly.

If the grader exits nonzero, prints invalid JSON, or leaves out any trial_id, set status to "grader_error". Put stderr and the last 40 lines of stdout in stderr.
Do not edit grade.py, answers.json, or the labels file.`,
      { label: `grade ${tag} ${i + 1}`, phase: phaseName, schema: GRADE_SCHEMA, model: RUNNER_MODEL });
  }));

  const byId = {};
  for (const r of results) {
    if (!r || r.status !== 'ok') return { error: r?.stderr ?? 'grader agent returned no result' };
    for (const g of r.results) byId[g.trial_id] = g;
  }
  const missing = items.filter(t => !byId[t.trialId]).map(t => t.trialId);
  if (missing.length) return { error: `grader returned no result for ${missing.length} trials, first: ${missing.slice(0, 5).join(', ')}` };
  for (const t of items) {
    t.grade = byId[t.trialId];
    t.labelPass = t.grade.category_ok && t.grade.priority_ok;
  }
  return { ok: true };
}

// ================= Run =================
const projected = cells.length * TRIALS * EST_TRIAL_USD + new Set(cells.map(c => c.ticket)).size * EST_JUDGE_USD;
log(`Round ${ROUND}${DRY ? ' DRY RUN' : ''}: ${cells.length} cells x ${TRIALS} trials, configs ${CONFIGS.join(', ')}, cap $${CAP_USD}, projected $${projected.toFixed(2)} (unmeasured)`);
if (projected > CAP_USD) log(`WARNING: projected spend is over the cap. Some trials will be skipped and logged.`);

// Trials. The trial index is the outer loop, so a cap hit skips trials evenly across configs.
phase('Trials');
const baseJobs = [];
for (let n = 1; n <= TRIALS; n++) for (const cell of cells) baseJobs.push(() => runTrial(cell, n, 'base'));
const trials = await parallel(baseJobs);

// Leak scan
phase('Leak scan');
const voided = await scanTrials(trials, 'base', 'Leak scan');

// Grade
phase('Grade');
const g1 = await gradeTrials(trials, 'base', 'Grade');
if (g1.error) {
  log(`HALT: grader error. ${g1.error}`);
  return { round: ROUND, halted: true, reason: `broken grader: ${g1.error}`, spent_usd: r2(spentUsd), skips, voided };
}

// Top-up split cells. Money for the judge is held back first.
phase('Top-up');
const ticketsWithTrials = new Set(trials.filter(t => t.status === 'completed' && !t.void).map(t => t.ticket));
const judgeHold = ticketsWithTrials.size * EST_JUDGE_USD;
const splitCells = cells.filter(cell => {
  const done = trials.filter(t => t.key === cell.key && t.grade);
  const passes = done.filter(t => t.labelPass).length;
  return passes > 0 && passes < done.length;
});
log(`Top-up: ${splitCells.length} split cells, up to ${TOPUP_MAX} extra trials each`);
const topupJobs = [];
for (let n = 1; n <= TOPUP_MAX; n++) for (const cell of splitCells) topupJobs.push(() => runTrial(cell, n, 'topup', judgeHold));
const topups = topupJobs.length ? await parallel(topupJobs) : [];
if (topups.length) {
  voided.push(...await scanTrials(topups, 'topup', 'Top-up'));
  const g2 = await gradeTrials(topups, 'topup', 'Top-up');
  if (g2.error) {
    log(`HALT: grader error in top-up. ${g2.error}`);
    return { round: ROUND, halted: true, reason: `broken grader: ${g2.error}`, spent_usd: r2(spentUsd), skips, voided };
  }
}
const allTrials = trials.concat(topups);

// Judge reply tone, blind to config, one call per ticket
phase('Judge');
log('Judge note: the Opus judge is in the same model family as the triage models. No cross-family judge is used this round.');
const judgeTickets = [...new Set(allTrials.filter(t => t.status === 'completed' && !t.void).map(t => t.ticket))];
await parallel(judgeTickets.map(ticket => async () => {
  const pool = shuffle(allTrials.filter(t => t.ticket === ticket && t.status === 'completed' && !t.void), `r${RR}-${ticket}`);
  if (!pool.length) return;
  if (!reserve('judge', ticket, EST_JUDGE_USD)) return;
  const idMap = {};
  pool.forEach((t, i) => { idMap[`R${i + 1}`] = t; });
  const out = await agent(
`You judge the tone of draft support replies. Read the rubric in spe/evals/graders/judge.md and follow it exactly.
Read the ticket at spe/evals/tasks/tickets/${ticket}.json.
Score each reply below on tone only, from 1 to 5, and set pass as the rubric defines it. Do not score the category or priority.
The replies come from different setups in a shuffled order. Do not guess which setup wrote which reply. Give a one-sentence reason for each score.

${Object.entries(idMap).map(([rid, t]) => `--- ${rid} ---\n${t.reply ?? '(empty reply)'}`).join('\n\n')}`,
    { label: `judge ${ticket}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL });
  if (!out) { log(`Judge for ${ticket} returned no result. Its replies stay unjudged.`); return; }
  for (const s of out.scores) {
    const t = idMap[s.reply_id];
    if (t) t.tone = { score: s.tone_score, pass: s.pass, reason: s.reason };
  }
}));

// ---------- Synthesis ----------
phase('Synthesis');
function summarize(ts) {
  const done = ts.filter(t => t.status === 'completed' && !t.void && t.grade);
  const judged = done.filter(t => t.tone);
  const m = k => mean(done.map(t => t.metrics?.[k]).filter(x => typeof x === 'number'));
  return {
    n_planned: ts.length,
    n_completed: done.length,
    n_harness_error: ts.filter(t => t.status === 'harness_error').length,
    n_skipped: ts.filter(t => t.status === 'skipped').length,
    n_void: ts.filter(t => t.void).length,
    category_acc: mean(done.map(t => (t.grade.category_ok ? 1 : 0))),
    priority_acc: mean(done.map(t => (t.grade.priority_ok ? 1 : 0))),
    both_acc: mean(done.map(t => (t.labelPass ? 1 : 0))),
    tone_pass_rate: mean(judged.map(t => (t.tone.pass ? 1 : 0))),
    tone_mean: mean(judged.map(t => t.tone.score)),
    n_judged: judged.length,
    mean_runtime_s: m('runtime_s'),
    mean_tool_calls: m('tool_calls'),
    mean_tool_errors: m('tool_errors'),
    mean_tokens: mean(done.map(t => (t.metrics?.input_tokens ?? 0) + (t.metrics?.output_tokens ?? 0))),
    mean_cost_usd: m('cost_usd'),
  };
}
const metrics = {};
for (const config of CONFIGS) {
  metrics[config] = {
    base: summarize(trials.filter(t => t.config === config)),
    with_topup: summarize(allTrials.filter(t => t.config === config)),
  };
}
const cellTable = cells.map(cell => {
  const done = trials.filter(t => t.key === cell.key && t.grade);
  return { key: cell.key, completed: done.length, label_passes: done.filter(t => t.labelPass).length,
    topups: topups.filter(t => t.key === cell.key && t.status !== 'skipped').length };
});

const failures = allTrials
  .filter(t => t.grade && (!t.labelPass || (t.tone && !t.tone.pass)))
  .map(t => ({ trial_id: t.trialId, config: t.config, ticket: t.ticket, kind: t.kind,
    got: t.label, expected: { category: t.grade.expected_category, priority: t.grade.expected_priority },
    tone: t.tone ?? null }));
const harnessErrors = allTrials.filter(t => t.status === 'harness_error').map(t => ({ trial_id: t.trialId, error: t.error }));

const [failureAnalysis, critic] = await parallel([
  () => agent(
`You analyze failures from an eval of the triage agent (configs ${CONFIGS.join(', ')}).
Group the failed trials below into failure types. For each type give name, kind (label, tone, or harness), configs, trial_ids, what happened, how to spot it, and a proposed fix.
Read spe/failures.md. If a type matches an existing F-number, put that F-number in matches_existing.
Then propose changes for round ${ROUND + 1}, each with a reason and the trial evidence.
Do not edit any file.

Metrics: ${JSON.stringify(metrics)}
Failed trials: ${JSON.stringify(failures)}
Harness errors (not model failures): ${JSON.stringify(harnessErrors)}`,
    { label: 'failure analysis', phase: 'Synthesis', schema: FAILURE_SCHEMA, model: 'opus' }),
  () => agent(
`You are the completeness critic for round ${ROUND} of an eval. Say what is missing or untrustworthy before the results are closed out.
Check that every cell has ${TRIALS} completed base trials, or that each shortfall is explained by a skip, a void, or a harness error.
Check that every completed trial has a code grade and a tone score. Check the spend against the $${CAP_USD} cap.
Check the voids for signs of an answer-key leak. Note that the judge is in the same model family as the triage models.
Mark complete true only if nothing is a blocker. Do not edit any file.

Cells: ${JSON.stringify(cellTable)}
Metrics: ${JSON.stringify(metrics)}
Skips: ${JSON.stringify(skips)}
Voided: ${JSON.stringify(voided)}
Harness errors: ${JSON.stringify(harnessErrors)}
Spent (reconciled estimate): $${r2(spentUsd)}`,
    { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: 'opus' }),
]);

log(`Done. Spent about $${r2(spentUsd)} of $${CAP_USD}. Skipped ${skips.length}. Voided ${voided.length}.`);

return {
  round: ROUND,
  dry_run: DRY,
  configs: CONFIGS,
  args_used: { tickets: TICKETS.length, trials: TRIALS, cap_usd: CAP_USD, est_trial_usd: EST_TRIAL_USD,
    est_judge_usd: EST_JUDGE_USD, topup_max: TOPUP_MAX, only: args.only ?? null },
  spend: { cap_usd: CAP_USD, spent_usd: r2(spentUsd) },
  metrics,
  cells: cellTable,
  skips,
  voided,
  harness_errors: harnessErrors,
  trials: allTrials.map(t => ({ trial_id: t.trialId, config: t.config, ticket: t.ticket, kind: t.kind, status: t.status,
    void: t.void ?? null, label: t.label ?? null, grade: t.grade ?? null, tone: t.tone ?? null, metrics: t.metrics ?? null })),
  failure_analysis: failureAnalysis,
  critic,
  notes: ['The headline numbers use base trials only, to match the saved prediction. The with_topup numbers are extra information.',
    'The judge is Opus, the same family as the triage models. No cross-family judge was used.'],
};
```
